#include <stdio.h>

const char* xmysql_status_str(long long value);
const char* xmysql_cmd_name(long long value);

/* 仅记录当前协议映射，不能把这些实际输出当成正确答案。 */
int main(void)
{
    printf("status-0100=%s\n", xmysql_status_str(0x0100));
    printf("status-4000=%s\n", xmysql_status_str(0x4000));
    printf("command-001f=%s\n", xmysql_cmd_name(0x001f));
    return 0;
}
